678	/** Rows whose content differs from the last acknowledged push. */
679	function changedRows<T>(
680	  next: T[],
681	  previous: T[] | undefined,
682	  identify: (row: T) => string,
683	): T[] {
684	  if (!previous) return next;
685	  const before = new Map(
686	    previous.map((row) => [identify(row), serialize(row)]),
687	  );
688	  return next.filter((row) => before.get(identify(row)) !== serialize(row));
689	}
