691	/**
692	 * Rows present in the last acknowledged push but missing from the next
693	 * snapshot. These were deleted locally and have to be told to leave the server
694	 * too — a section that only ever upserts would otherwise keep them forever.
695	 */
696	function removedRows<T>(
697	  next: T[],
698	  previous: T[] | undefined,
699	  identify: (row: T) => string,
700	): string[] {
701	  if (!previous) return [];
702	  const keys = new Set(next.map(identify));
703	  return previous
704	    .filter((row) => !keys.has(identify(row)))
705	    .map((row) => identify(row));
706	}
