1	import type {
2	  DossierAttachment,
3	  DossierProbe,
4	  ProjectBrief,
5	  ProjectInterviewAnswers,
6	} from "../types";
7	import { markDirty as markSyncDirty } from "./convex-sync";
8	import { BRIEF_PATH, writeFileAsJson } from "./lix";
9	import {
10	  loadActiveFolioIdFromIdb,
11	  loadBriefFromIdb,
12	  loadFolioContentFromIdb,
13	  saveBriefToIdb,
14	} from "./idb";
15	import { archiveBriefEdition } from "./brief-history";
16	
17	export const BRIEF_STORAGE_KEY = "twyne-project-brief";
18	export const DRAFT_STORAGE_KEY = "twyne-document";
19	/**
20	 * One-shot slot for the manuscript text that should travel with a writer
21	 * when they hit "Start over" on the dossier refinery. The refine route
22	 * stashes the current folio content here before routing to /dossier/create,
23	 * and the create route reads it on hydration to seed the next interview's
24	 * starting-material field. Either side clears it once consumed.
25	 */
26	export const STARTING_MATERIAL_KEY = "twyne-starting-material";
27	
28	export const DEFAULT_INTERVIEW_ANSWERS: ProjectInterviewAnswers = {
29	  workingTitle: "Untitled project",
30	  format: "Essay",
31	  audience: "A thoughtful reader who needs the point made clearly",
32	  goal: "Make the central argument feel inevitable and worth caring about",
33	  tone: "Clear, exact, and generous",
34	  constraints: "Keep the piece grounded in evidence and avoid generic filler",
35	  successSignal:
36	    "A reader should know what this is, who it is for, and why it matters",
37	};
38	
39	/** The name a folio gets when the writer didn't give it one. */
40	export const UNTITLED_FOLIO_NAME = "Untitled folio";
41	
42	/** A folio's name as a brief title, or "" when the folio is unnamed. */
43	export function briefTitleFromFolioName(
44	  name: string | null | undefined,
45	): string {
46	  const title = name?.trim() ?? "";
47	  return title === UNTITLED_FOLIO_NAME ? "" : title;
48	}
49	
50	/**
51	 * Carry a named folio's title into the brief when the writer left the
52	 * working title blank or at the form's placeholder.
53	 */
54	export function withFolioTitle(
55	  answers: ProjectInterviewAnswers,
56	  folioName: string | null | undefined,
57	): ProjectInterviewAnswers {
58	  const folioTitle = briefTitleFromFolioName(folioName);
59	  const current = answers.workingTitle.trim();
60	  if (!folioTitle) return answers;
61	  if (current && current !== DEFAULT_INTERVIEW_ANSWERS.workingTitle) {
62	    return answers;
63	  }
64	  return { ...answers, workingTitle: folioTitle };
65	}
66	
67	export function createProjectBrief(
68	  answers: ProjectInterviewAnswers,
69	  previous?: ProjectBrief | null,
70	  attachments?: DossierAttachment[],
71	  probes?: DossierProbe[],
72	): ProjectBrief {
73	  const now = Date.now();
74	  const carried = probes ?? previous?.probes;
75	  return {
76	    answers: normalizeInterviewAnswers(answers),
77	    attachments: attachments ?? previous?.attachments ?? [],
78	    // Omitted entirely rather than stored as [] so a brief that never had
79	    // probes stays byte-identical to one written before they existed.
80	    ...(carried && carried.length > 0 ? { probes: carried } : {}),
81	    completedAt: previous?.completedAt ?? now,
82	    updatedAt: now,
83	  };
84	}
85	
86	export function loadProjectBrief(): ProjectBrief | null {
87	  if (typeof window === "undefined") return null;
88	  try {
89	    const raw = localStorage.getItem(BRIEF_STORAGE_KEY);
90	    if (!raw) return null;
91	    const parsed = JSON.parse(raw) as Partial<ProjectBrief> & {
92	      answers?: ProjectInterviewAnswers;
93	    };
94	    if (!parsed.answers) return null;
95	    return normalizeProjectBrief(parsed);
96	  } catch {
97	    return null;
98	  }
99	}
100	
101	export async function loadProjectBriefForFolio(
102	  folioId: string | null | undefined,
103	): Promise<ProjectBrief | null> {
104	  if (!folioId) return null;
105	  const brief = await loadBriefFromIdb(folioId);
106	  return brief ? normalizeProjectBrief(brief) : null;
107	}
108	
109	export function saveProjectBrief(brief: ProjectBrief): void {
110	  if (typeof window === "undefined") return;
111	  try {
112	    localStorage.setItem(BRIEF_STORAGE_KEY, JSON.stringify(brief));
113	    void writeFileAsJson(BRIEF_PATH, brief).then(() => {
114	      markSyncDirty();
115	    });
116	  } catch {
117	    // storage unavailable
118	  }
119	}
120	
121	export async function saveProjectBriefForFolio(
122	  folioId: string,
123	  brief: ProjectBrief,
124	): Promise<void> {
125	  const normalized = normalizeProjectBrief(brief);
126	  const previous = await loadBriefFromIdb(folioId);
127	  if (previous && JSON.stringify(previous) !== JSON.stringify(normalized)) {
128	    await archiveBriefEdition(folioId, normalizeProjectBrief(previous));
129	  }
130	  await saveBriefToIdb(folioId, normalized);
131	  // The IDB helper absorbs storage failures; verify the write so a lost
132	  // dossier surfaces as an error instead of a silent "filed" stamp.
133	  const saved = await loadBriefFromIdb(folioId);
134	  if (saved?.updatedAt !== normalized.updatedAt) {
135	    throw new Error("The dossier could not be saved on this device.");
136	  }
137	
138	  // Keep the legacy mirrors current during the per-folio migration. They are
139	  // no longer authoritative, but older routes and existing Lix histories can
140	  // still open the most recently filed dossier.
141	  saveProjectBrief(normalized);
142	  await writeFileAsJson(`/folios/${folioId}/brief.json`, normalized);
143	  markSyncDirty();
144	}
145	
146	export function normalizeProjectBrief(
147	  parsed: Partial<ProjectBrief> & {
148	    answers?: ProjectInterviewAnswers;
149	  },
150	): ProjectBrief {
151	  const probes = Array.isArray(parsed.probes) ? parsed.probes : [];
152	  return {
153	    answers: normalizeInterviewAnswers(
154	      parsed.answers ?? DEFAULT_INTERVIEW_ANSWERS,
155	    ),
156	    attachments: Array.isArray(parsed.attachments) ? parsed.attachments : [],
157	    ...(probes.length > 0 ? { probes } : {}),
158	    completedAt:
159	      typeof parsed.completedAt === "number" ? parsed.completedAt : Date.now(),
160	    updatedAt:
161	      typeof parsed.updatedAt === "number" ? parsed.updatedAt : Date.now(),
162	  };
163	}
164	
165	/**
166	 * Read the live draft.
167	 *
168	 * The store of record is folio-scoped IndexedDB. There used to be a parallel
169	 * mirror in a single global `localStorage` key, written synchronously on a
170	 * timer while the writer typed — it blocked the main thread, carried the whole
171	 * manuscript, and because it was one key for all folios it held whichever
172	 * folio happened to save last. It is gone; this reads the active folio.
173	 */
174	export async function loadDraftHtml(): Promise<string> {
175	  if (typeof window === "undefined") return "";
176	  const folioId = await loadActiveFolioIdFromIdb();
177	  if (!folioId) return "";
178	  return (await loadFolioContentFromIdb(folioId)) || "";
179	}
180	
181	export async function loadDraftText(): Promise<string> {
182	  return htmlToPlainText(await loadDraftHtml());
183	}
184	
185	/**
186	 * The pre-folio draft key. Read once by the editor's migration path to seed
187	 * "Folio I" for writers who last opened Twyne before folios existed. Nothing
188	 * writes this key any more.
189	 */
190	export function loadLegacyDraftHtml(): string {
191	  if (typeof window === "undefined") return "";
192	  try {
193	    return localStorage.getItem(DRAFT_STORAGE_KEY) || "";
194	  } catch {
195	    return "";
196	  }
197	}
198	
199	/* ── Crash mirror ───────────────────────────────────────────────────────
200	 *
201	 * IndexedDB is the store of record, but a write started as the tab is closing
202	 * is not guaranteed to commit — the browser can tear the page down first.
203	 * localStorage is synchronous, so a write there does survive.
204	 *
205	 * That is the *only* reason this exists, so it is written exactly once per
206	 * departure (`pagehide` / tab hidden) rather than on a typing timer, and it is
207	 * scoped to a folio so it cannot overwrite a different manuscript the way the
208	 * old single global draft key did.
209	 */
210	const CRASH_MIRROR_KEY = "twyne:draft-crash-mirror";
211	
212	interface CrashMirror {
213	  folioId: string;
214	  html: string;
215	  savedAt: number;
216	}
217	
218	/** Synchronously stash the manuscript on the way out. Safe to call often. */
219	export function writeCrashMirror(folioId: string, html: string): void {
220	  if (typeof window === "undefined" || !folioId) return;
221	  try {
222	    const entry: CrashMirror = { folioId, html, savedAt: Date.now() };
223	    localStorage.setItem(CRASH_MIRROR_KEY, JSON.stringify(entry));
224	  } catch {
225	    // Quota or private mode — the IndexedDB write is still the main path.
226	  }
227	}
228	
229	/**
230	 * The stashed manuscript for `folioId`, if the last departure left one.
231	 *
232	 * Returns it whenever it exists: it was written *after* the IndexedDB write
233	 * was issued, so either that write landed (and the two agree, making this a
234	 * no-op) or it did not (and this is the only surviving copy).
235	 */
236	export function readCrashMirror(folioId: string): string | null {
237	  if (typeof window === "undefined" || !folioId) return null;
238	  try {
239	    const raw = localStorage.getItem(CRASH_MIRROR_KEY);
240	    if (!raw) return null;
241	    const entry = JSON.parse(raw) as CrashMirror;
242	    return entry.folioId === folioId ? entry.html : null;
243	  } catch {
244	    return null;
245	  }
246	}
247	
248	export function clearCrashMirror(): void {
249	  if (typeof window === "undefined") return;
250	  try {
251	    localStorage.removeItem(CRASH_MIRROR_KEY);
252	  } catch {
253	    // nothing to clear
254	  }
255	}
256	
257	export function loadStartingMaterial(): string {
258	  if (typeof window === "undefined") return "";
259	  try {
260	    return localStorage.getItem(STARTING_MATERIAL_KEY) || "";
261	  } catch {
262	    return "";
263	  }
264	}
265	
266	export function saveStartingMaterial(material: string): void {
267	  if (typeof window === "undefined") return;
268	  try {
269	    localStorage.setItem(STARTING_MATERIAL_KEY, material);
270	  } catch {
271	    // storage unavailable
272	  }
273	}
274	
275	export function clearStartingMaterial(): void {
276	  if (typeof window === "undefined") return;
277	  try {
278	    localStorage.removeItem(STARTING_MATERIAL_KEY);
279	  } catch {
280	    // storage unavailable
281	  }
282	}
283	
284	export function buildStarterDocument(answers: ProjectInterviewAnswers): string {
285	  const normalized = normalizeInterviewAnswers(answers);
286	  const title = escapeHtml(normalized.workingTitle);
287	
288	  return `
289	    <h1>${title}</h1>
290	    <p><strong>Anti-tabula rasa brief</strong>: this draft starts with context, not emptiness.</p>
291	    <h2>Working context</h2>
292	    <ul>
293	      <li><strong>Format:</strong> ${escapeHtml(normalized.format)}</li>
294	      <li><strong>Audience:</strong> ${escapeHtml(normalized.audience)}</li>
295	      <li><strong>Goal:</strong> ${escapeHtml(normalized.goal)}</li>
296	      <li><strong>Tone:</strong> ${escapeHtml(normalized.tone)}</li>
297	      <li><strong>Constraints:</strong> ${escapeHtml(normalized.constraints)}</li>
298	      <li><strong>Success signal:</strong> ${escapeHtml(normalized.successSignal)}</li>
299	    </ul>
300	    <h2>Starter prompt</h2>
301	    <blockquote>
302	      <p>${escapeHtml(normalized.goal)}</p>
303	    </blockquote>
304	    <p>Begin the draft here. The room will use the brief above as the anchor.</p>
305	  `.trim();
306	}
307	
308	export function buildImportedMaterialDocument(
309	  answers: ProjectInterviewAnswers,
310	  raw: string,
311	  filename?: string,
312	): string {
313	  const normalized = normalizeInterviewAnswers(answers);
314	  const title = escapeHtml(normalized.workingTitle);
315	  const sourceLabel = filename?.trim()
316	    ? `Imported from ${escapeHtml(filename.trim())}`
317	    : "Imported material";
318	  const paragraphs = raw
319	    .trim()
320	    .split(/\n{2,}/)
321	    .map(
322	      (paragraph) => `<p>${escapeHtml(paragraph).replace(/\n/g, "<br>")}</p>`,
323	    )
324	    .join("\n");
325	
326	  return `
327	    <h1>${title}</h1>
328	    <p><strong>${sourceLabel}</strong>: this material was brought into the room during onboarding.</p>
329	    ${paragraphs}
330	  `.trim();
331	}
332	
333	export function summarizeBrief(brief: ProjectBrief | null): string {
334	  const answers = brief?.answers ?? DEFAULT_INTERVIEW_ANSWERS;
335	  return `${answers.format} for ${answers.audience}. Goal: ${answers.goal}`;
336	}
337	
338	export function htmlToPlainText(html: string): string {
339	  return html
340	    .replace(/<style[\s\S]*?<\/style>/gi, " ")
341	    .replace(/<script[\s\S]*?<\/script>/gi, " ")
342	    .replace(/<\/(p|h[1-6]|li|blockquote|tr|div)>/gi, "\n")
343	    .replace(/<[^>]+>/g, " ")
344	    .replace(/&nbsp;/g, " ")
345	    .replace(/&amp;/g, "&")
346	    .replace(/&lt;/g, "<")
347	    .replace(/&gt;/g, ">")
348	    .replace(/&quot;/g, '"')
349	    .replace(/&#39;/g, "'")
350	    .replace(/[ \t]+/g, " ")
351	    .replace(/\n{3,}/g, "\n\n")
352	    .trim();
353	}
354	
355	function normalizeInterviewAnswers(
356	  answers: ProjectInterviewAnswers,
357	): ProjectInterviewAnswers {
358	  return {
359	    workingTitle:
360	      answers.workingTitle.trim() || DEFAULT_INTERVIEW_ANSWERS.workingTitle,
361	    format: answers.format.trim() || DEFAULT_INTERVIEW_ANSWERS.format,
362	    audience: answers.audience.trim() || DEFAULT_INTERVIEW_ANSWERS.audience,
363	    goal: answers.goal.trim() || DEFAULT_INTERVIEW_ANSWERS.goal,
364	    tone: answers.tone.trim() || DEFAULT_INTERVIEW_ANSWERS.tone,
