 * Project only the evidence a policy question needs. In particular, this does
 * not serialize provider/model settings or the whole writer profile into the
 * judgement state.
 */
export function buildEditorialPolicyState(
  input: EditorialPolicyInput,
): Record<string, string> {
  const answers = input.brief?.answers;
  const persona = input.persona;
  const profile = input.profile;

  const privateContext = [
    profile?.personalFacts?.trim(),
    profile?.feedbackNotes?.trim(),
    profile?.feedbackAvoid?.trim(),
  ].filter((value): value is string => Boolean(value));

  return {
    policyVersion: EDITORIAL_POLICY_VERSION,
    policyReply: text(input.note),
    policyPassage: text(input.quote),
    policyDraft: text(input.draft, 24_000),
    policyOperation: input.operation ?? "feedback",
    policyUserMessage: text(input.userMessage),
    policyPersona: persona
      ? [
          `Name: ${text(persona.name, 500)}`,
          `Role: ${text(persona.role, 500)}`,
          `Description: ${text(persona.description, 4_000)}`,
          `Focus: ${text(persona.focus, 4_000)}`,
          `Doctrine: ${text(persona.criticalMethod, 4_000)}`,
          `Voice: ${text(persona.voice, 4_000)}`,
          `Avoidances:\n${list(persona.avoidances)}`,
        ].join("\n")
      : "(no persona supplied)",
    policyBrief: answers
      ? [
          `Audience: ${text(answers.audience)}`,
          `Goal: ${text(answers.goal)}`,
          `Tone: ${text(answers.tone)}`,
          `Constraints: ${text(answers.constraints)}`,
  const state: Record<string, string> = {
    note: input.note,
    passage: input.quote,
  };
  if (input.persona) state.advisor = input.persona;
  if (input.draftExcerpt) state.draft = input.draftExcerpt;

  const a = input.brief?.answers;
  if (a) {
    if (a.audience) state.audience = a.audience;
    if (a.goal) state.goal = a.goal;
    if (a.tone) state.tone = a.tone;
    if (a.constraints) state.constraints = a.constraints;
    if (a.successSignal) state.successSignal = a.successSignal;
  }

  if (input.writerProfile) {
    const wp = input.writerProfile;
    if (wp.personalFacts?.trim()) {
      state.writerFacts = wp.personalFacts.trim();
    }
export function buildDossierResearchInstructions(
  brief: ProjectBrief | null,
): string {
  if (!brief) {
    return [
      "Research mode selected from Dossier: GENERAL (no Dossier available).",
      "Treat real-world quotations, people, statistics, events, works, and factual claims as checkable, while leaving clearly invented material alone.",
    ].join("\n");
  }

  const mode = dossierResearchMode(brief);
  const a = brief.answers;
  const lines = [
    `Research mode selected from Dossier: ${mode.toUpperCase()}.`,
    "Dossier particulars:",
    `- Format: ${compactDossierValue(a.format)}`,
    `- Working title: ${compactDossierValue(a.workingTitle)}`,
    `- Audience: ${compactDossierValue(a.audience)}`,
    `- Goal: ${compactDossierValue(a.goal)}`,
    `- Tone: ${compactDossierValue(a.tone)}`,
    `- Constraints: ${compactDossierValue(a.constraints)}`,
    `- Success signal: ${compactDossierValue(a.successSignal)}`,
  ];

  const answeredProbes = (brief.probes ?? [])
    .filter((probe) => probe.answer !== undefined)
    .slice(0, 6)
    .map((probe) => {
      const answer = Array.isArray(probe.answer)
        ? probe.answer.join("; ")
        : String(probe.answer);
      return `- ${compactDossierValue(probe.prompt, 240)} => ${compactDossierValue(answer, 300)}`;
    });

